import 'solid-js';

var l = ["<script", ' type="application/ld+json">', "<\/script>"], c = ["<nav", ' style="', '"><a href="/"><img src="/logo_cmi.png" alt="Creative Metal Industries" width="140" height="71"></a><div style="', '"></div><a href="/blog" style="', '">\u2190 All Articles</a></nav>'], g = ["<div", ' style="', '"><a href="/" style="', '">Home</a><span style="', '">\u203A</span><a href="/blog" style="', '">Blog</a><span style="', '">\u203A</span><span>Pipe Schedule Chart</span></div>'], h = ["<main", ' style="', '"><div style="', '"><span style="', '">Technical Reference</span><span style="', '">June 2026 \xB7 6 min read</span><h1 style="', '">Pipe Schedule SCH 40, 80, and 160 \u2014 Complete Weight and Thickness Chart Guide</h1><p style="', '">"What schedule pipe do I need?" \u2014 this is one of the most common questions asked by engineers and procurement teams specifying industrial piping. This reference guide explains what pipe schedule means, provides wall thickness charts for all common sizes, includes the weight calculation formula, and compares SCH 40, 80, and 160 for practical selection. As a <strong>steel stockist in Vadodara</strong> with all schedules in ready stock, Creative Metal Industries provides this as a free reference tool alongside our comprehensive <a href="/products" style="', '">steel weight charts</a> and <a href="/products" style="', '">MS angle ISMC weight chart</a>.</p></div><div style="', '"><h2 style="', '">What Does Pipe Schedule Mean?</h2><p style="', '">Pipe schedule is a <strong>dimensionless number</strong> that defines the wall thickness of a pipe for a given nominal size. It was originally derived from the formula:</p><div style="', '">Schedule Number \u2248 1000 \xD7 (P \xF7 S)</div><p style="', '">Where P = internal working pressure (psi) and S = allowable stress of the material (psi).</p><p style="', '">The key principle: <strong>for the same nominal pipe size (NPS), ALL schedules have the SAME outside diameter (OD)</strong>. Only the wall thickness changes. Higher schedule = thicker wall = smaller bore = higher pressure capacity = heavier pipe.</p></div><div style="', '"><h2 style="', '">Wall Thickness Chart \u2014 SCH 10S, 40, 80, 160 (mm)</h2><div style="', '"><table style="', '"><thead><tr style="', '"><th style="', '">NPS</th><th style="', '">OD (mm)</th><th style="', '">SCH 10S</th><th style="', '">SCH 40</th><th style="', '">SCH 80</th><th style="', '">SCH 160</th><th style="', '">XXS</th></tr></thead><tbody>', '</tbody></table></div><p style="', '">All values in mm. Per ASME B36.10M (carbon steel) and B36.19M (stainless steel). SCH 5S/10S are stainless steel schedules.</p></div><div style="', '"><h2 style="', '">Weight Calculation Formula</h2><div style="', '"><p style="', '">Weight (kg/m) = (OD \u2212 WT) \xD7 WT \xD7 0.02466 \xD7 Density Factor</p><p style="', '">Where OD = outside diameter (mm), WT = wall thickness (mm)</p></div><p style="', '"><strong>Density factors:</strong> Carbon Steel = 1.00 (7.85 g/cm\xB3) | Stainless Steel = 1.02 (8.0 g/cm\xB3) | Aluminium = 0.35</p><p style="', '"><strong>Example:</strong> 2" SCH 40 CS pipe: (60.3 \u2212 3.91) \xD7 3.91 \xD7 0.02466 = <strong>5.44 kg/m</strong></p></div><div style="', '"><h2 style="', '">SCH 40 vs SCH 80 vs SCH 160 \u2014 Key Differences</h2><div style="', '"><table style="', '"><thead><tr style="', '"><th style="', '">Factor</th><th style="', '">SCH 40</th><th style="', '">SCH 80</th><th style="', '">SCH 160</th></tr></thead><tbody>', '</tbody></table></div></div><div style="', '"><h2 style="', '">Applications for Each Schedule</h2><ul style="', `"><li><strong>SCH 5S / 10S:</strong> Low-pressure stainless steel process piping, pharmaceutical, food & dairy, instrument lines. Thin wall = economical for corrosion-resistant service where pressure is low.</li><li><strong>SCH 40 (STD):</strong> Most common industrial schedule. General process piping, water supply, fire protection, HVAC, low-to-moderate pressure process lines up to ~150\xB0C/20 bar.</li><li><strong>SCH 80 (XS):</strong> Higher-pressure process piping, steam lines, hydraulic systems, chemical injection. When SCH 40 isn't sufficient but full high-pressure isn't needed.</li><li><strong>SCH 120:</strong> Intermediate between 80 and 160. Less common \u2014 used when exact pressure calculation falls between 80 and 160 capabilities.</li><li><strong>SCH 160:</strong> High-pressure service \u2014 refinery process piping, boiler feed water, high-pressure steam, ammonia service. Significant cost and weight premium.</li><li><strong>XXS (Double Extra Strong):</strong> Maximum wall thickness. Extreme pressure (6000+ PSI), hydraulic jacks, high-pressure test lines, pipe used as structural columns.</li></ul></div><div style="`, '"><h2 style="', '">Why Source Pipes from Creative Metal Industries?</h2><ul style="', '"><li><strong>All schedules in stock:</strong> SCH 5S through XXS in carbon steel (ASTM A106/A53) and stainless steel (ASTM A312) at our Vadodara warehouse</li><li><strong>All sizes:</strong> 1/2" to 24" \u2014 seamless and welded \u2014 ready for immediate dispatch</li><li><strong>Weight charts available:</strong> Complete <a href="/products" style="', `">MS angle, ISMC, ISMB weight charts</a> and pipe schedule reference at our products page</li><li><strong>Cut-to-length:</strong> Pipe cutting to your exact requirements \u2014 no wastage on odd lengths</li><li><strong>Technical support:</strong> Not sure which schedule? Call us with your design pressure and temperature \u2014 we'll confirm the correct schedule per ASME B31.3</li><li><strong>Same-day dispatch:</strong> Standard schedules (40, 80) in common sizes ship same day from GIDC Makarpura, Vadodara</li></ul></div><div style="`, '"><h2 style="', '">Frequently Asked Questions \u2014 Pipe Schedules</h2><div style="', '">', '</div></div><div style="', '"><h2 style="', '">Need Pipes in Any Schedule?</h2><p style="', '">SCH 5S to XXS. Carbon steel + stainless steel. All sizes in ready stock at Vadodara. Same-day dispatch.</p><div style="', '"><a href="tel:+919998280619" style="', '">\u{1F4DE} +91 99982 80619</a><a href="https://wa.me/919998280619" target="_blank" rel="noopener" style="', '">\u{1F4AC} WhatsApp</a><a href="/products" style="', '">Full Weight Charts \u2192</a></div></div><h3 style="', '">Related Articles & Products</h3><div style="', '">', "</div></main>"], f = ["<footer", ' style="', '"><p><strong style="', '">Creative Metal Industries</strong> \u2014 Steel Stockist Vadodara | Pipe Schedule Chart | Weight Reference</p><p><a href="tel:+919998280619" style="', '">+91 99982 80619</a> | <a href="https://www.creativemetalind.com" style="', '">creativemetalind.com</a></p></footer>'], u = ["<tr", ' style="', '"><td style="', '">', '</td><td style="', '">', '</td><td style="', '">', '</td><td style="', '">', '</td><td style="', '">', '</td><td style="', '">', '</td><td style="', '">', "</td></tr>"], b = ["<tr", ' style="', '"><td style="', '">', '</td><td style="', '">', '</td><td style="', '">', '</td><td style="', '">', "</td></tr>"], y = ["<details", ' style="', '"><summary style="', '">', '</summary><p style="', '">', "</p></details>"], S = ["<a", ' style="', '"><!--$-->', "<!--/--> \u2192</a>"];
